using System.ComponentModel.DataAnnotations;
using System.Data;
using System.Text.Json;
using EventContracts;
using Microsoft.EntityFrameworkCore;
using QRCoder;

var builder=WebApplication.CreateBuilder(args);
builder.Logging.AddJsonConsole();
builder.Services.AddDbContext<EventDb>(o=>o.UseSqlServer(builder.Configuration.GetConnectionString("Events")??Environment.GetEnvironmentVariable("EVENTS_DB")??throw new InvalidOperationException("Configure the service SQL Server connection string.")));
builder.Services.AddHealthChecks();builder.Services.AddCors(o=>o.AddDefaultPolicy(p=>p.WithOrigins((builder.Configuration["Cors:AllowedOrigins"]??"http://localhost:5173,http://localhost:8080").Split(',',StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries)).AllowAnyHeader().AllowAnyMethod().AllowCredentials()));builder.Services.AddHostedService<DatabaseInitializer>();builder.Services.AddSingleton<OutboxPublisher>();builder.Services.AddHostedService(x=>x.GetRequiredService<OutboxPublisher>());builder.Services.AddEndpointsApiExplorer();builder.Services.AddSwaggerGen();
var app=builder.Build();
app.Use(async(c,n)=>{var id=c.Request.Headers["X-Correlation-ID"].FirstOrDefault();if(string.IsNullOrWhiteSpace(id))id=Guid.NewGuid().ToString("N");c.TraceIdentifier=id;c.Response.Headers["X-Correlation-ID"]=id;using(app.Logger.BeginScope(new Dictionary<string,object>{{"CorrelationId",id}}))await n();});
app.UseExceptionHandler(h=>h.Run(async c=>{c.Response.StatusCode=500;await Results.Problem("An unexpected error occurred.",statusCode:500,extensions:new Dictionary<string,object?>{{"correlationId",c.TraceIdentifier}}).ExecuteAsync(c);}));
app.UseCors();
app.UseSwagger();app.UseSwaggerUI();
app.MapHealthChecks("/health");app.MapGet("/health/live",()=>Results.Ok(new{status="live"}));app.MapGet("/health/ready",async(EventDb db,CancellationToken ct)=>await db.Database.CanConnectAsync(ct)?Results.Ok(new{status="ready"}):Results.StatusCode(503));
app.MapGet("/events",async(EventDb db,string? search,string? status,string? category,int page=1,int pageSize=12,string? sort="date",CancellationToken ct=default)=>{page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);var q=db.Events.AsNoTracking().AsQueryable();if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.Name.Contains(search));if(!string.IsNullOrWhiteSpace(status))q=q.Where(x=>x.Status==status);if(!string.IsNullOrWhiteSpace(category))q=q.Where(x=>x.Category==category);var total=await q.CountAsync(ct);q=sort=="name"?q.OrderBy(x=>x.Name):q.OrderBy(x=>x.StartTime);return Results.Ok(new{items=await q.Skip((page-1)*pageSize).Take(pageSize).Select(EventDto.Map).ToListAsync(ct),page,pageSize,total});});
app.MapGet("/admin/events",async(EventDb db,string? search,string? status,string? category,int page=1,int pageSize=20,CancellationToken ct=default)=>{page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);var q=db.Events.AsNoTracking().AsQueryable();if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.Name.Contains(search));if(!string.IsNullOrWhiteSpace(status))q=q.Where(x=>x.Status==status);if(!string.IsNullOrWhiteSpace(category))q=q.Where(x=>x.Category==category);var total=await q.CountAsync(ct);return Results.Ok(new{items=await q.OrderByDescending(x=>x.CreatedAt).Skip((page-1)*pageSize).Take(pageSize).Select(EventDto.Map).ToListAsync(ct),page,pageSize,total});});
app.MapGet("/events/{id:guid}",async(Guid id,EventDb db,CancellationToken ct)=>await db.Events.AsNoTracking().Where(x=>x.Id==id).Select(EventDto.Map).FirstOrDefaultAsync(ct) is{} e?Results.Ok(e):Results.NotFound());
app.MapPost("/events",CreateEvent);app.MapPost("/admin/events",CreateEvent);
app.MapPut("/events/{id:guid}",UpdateEvent);app.MapPut("/admin/events/{id:guid}",UpdateEvent);
app.MapDelete("/events/{id:guid}",DeleteEvent);app.MapDelete("/admin/events/{id:guid}",DeleteEvent);
app.MapPost("/events/{id:guid}/registrations",async(Guid id,RegistrationInput input,EventDb db,HttpContext http,CancellationToken ct)=>{var errors=Validate(input);if(errors.Count>0)return Results.ValidationProblem(errors);await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable,ct);var e=await db.Events.SingleOrDefaultAsync(x=>x.Id==id,ct);if(e is null)return Results.NotFound();var email=input.Email.Trim().ToLowerInvariant();var duplicate=await db.Registrations.AnyAsync(x=>x.EventId==id&&x.Participant.Email==email&&x.Status!="Cancelled",ct);var admission=RegistrationRules.CheckRegistration(e,duplicate,DateTimeOffset.UtcNow);if(admission is not null)return Results.Conflict(new{message=admission});var p=await db.Participants.SingleOrDefaultAsync(x=>x.Email==email,ct);if(p is null){p=new(){FullName=input.FullName.Trim(),Email=email,Phone=input.Phone.Trim(),StudentCode=input.StudentCode?.Trim(),CreatedAt=DateTimeOffset.UtcNow};db.Participants.Add(p);}else{p.FullName=input.FullName.Trim();p.Phone=input.Phone.Trim();p.StudentCode=input.StudentCode?.Trim();}var r=new Registration{Id=Guid.NewGuid(),EventId=id,Event=e,Participant=p,RegistrationCode="EVT-"+Convert.ToHexString(Guid.NewGuid().ToByteArray())[..12],RegistrationDate=DateTimeOffset.UtcNow,Status="Registered",CreatedAt=DateTimeOffset.UtcNow};r.QRCodeData="event-checkin:"+r.RegistrationCode;e.RegisteredCount++;e.UpdatedAt=DateTimeOffset.UtcNow;db.Registrations.Add(r);db.AddOutbox(r,e,p,"ParticipantRegistered",http.TraceIdentifier);await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return Results.Created($"/registrations/{r.Id}",RegistrationDto.From(r,e));});
app.MapDelete("/registrations/{id:guid}",async(Guid id,EventDb db,HttpContext http,CancellationToken ct)=>{await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable,ct);var r=await db.Registrations.Include(x=>x.Event).Include(x=>x.Participant).SingleOrDefaultAsync(x=>x.Id==id,ct);if(r is null)return Results.NotFound();if(RegistrationRules.CheckCancellation(r.Status) is{} cancelError)return Results.Conflict(new{message=cancelError});r.Status="Cancelled";r.UpdatedAt=DateTimeOffset.UtcNow;r.Event.RegisteredCount--;r.Event.UpdatedAt=DateTimeOffset.UtcNow;db.AddOutbox(r,r.Event,r.Participant,"ParticipantCancelled",http.TraceIdentifier);await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return Results.NoContent();});
app.MapPost("/checkin/verify",async(VerifyInput input,EventDb db,CancellationToken ct)=>{var key=input.RegistrationCode.Replace("event-checkin:","",StringComparison.OrdinalIgnoreCase).Trim();var r=await db.Registrations.AsNoTracking().Include(x=>x.Event).Include(x=>x.Participant).SingleOrDefaultAsync(x=>x.RegistrationCode==key,ct);return r is null?Results.NotFound(new{message="Registration code was not found."}):Results.Ok(RegistrationDto.From(r,r.Event));});
app.MapPost("/registrations/lookup",async(LookupInput input,EventDb db,CancellationToken ct)=>{var errors=Validate(input);if(errors.Count>0)return Results.ValidationProblem(errors);var query=input.Query.Trim();var code=query.Replace("event-checkin:","",StringComparison.OrdinalIgnoreCase);var q=db.Registrations.AsNoTracking().Include(x=>x.Event).Include(x=>x.Participant).Where(x=>x.RegistrationCode==code||x.Participant.Email==query.ToLowerInvariant());var rows=await q.OrderByDescending(x=>x.RegistrationDate).Take(25).ToListAsync(ct);return Results.Ok(new{items=rows.Select(x=>RegistrationDto.From(x,x.Event)),total=rows.Count});});
app.MapPost("/registrations/{id:guid}/checkin",async(Guid id,EventDb db,HttpContext http,CancellationToken ct)=>{await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable,ct);var r=await db.Registrations.Include(x=>x.Event).Include(x=>x.Participant).SingleOrDefaultAsync(x=>x.Id==id,ct);if(r is null)return Results.NotFound();if(RegistrationRules.CheckCheckIn(r.Status) is{} checkinError)return Results.Conflict(new{message=checkinError});r.Status="CheckedIn";r.CheckInTime=DateTimeOffset.UtcNow;r.UpdatedAt=DateTimeOffset.UtcNow;r.Event.CheckedInCount++;r.Event.UpdatedAt=DateTimeOffset.UtcNow;db.AddOutbox(r,r.Event,r.Participant,"ParticipantCheckedIn",http.TraceIdentifier);await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return Results.Ok(RegistrationDto.From(r,r.Event));});
app.MapGet("/registrations/{id:guid}",async(Guid id,EventDb db,CancellationToken ct)=>await db.Registrations.AsNoTracking().Include(x=>x.Participant).Include(x=>x.Event).SingleOrDefaultAsync(x=>x.Id==id,ct) is{} r?Results.Ok(RegistrationDto.From(r,r.Event)):Results.NotFound());
app.MapGet("/registrations/{id:guid}/qrcode",async(Guid id,EventDb db,CancellationToken ct)=>{var data=await db.Registrations.AsNoTracking().Where(x=>x.Id==id).Select(x=>x.QRCodeData).SingleOrDefaultAsync(ct);if(data is null)return Results.NotFound();using var gen=new QRCodeGenerator();using var qr=gen.CreateQrCode(data,QRCodeGenerator.ECCLevel.Q);return Results.File(new PngByteQRCode(qr).GetGraphic(8),"image/png",$"registration-{id}.png");});
app.MapGet("/events/{id:guid}/registrations",RegistrationList);app.MapGet("/admin/registrations",RegistrationList);
app.MapGet("/admin/participants",async(EventDb db,string? search,int page=1,int pageSize=20,CancellationToken ct=default)=>{page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);var q=db.Participants.AsNoTracking().AsQueryable();if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.FullName.Contains(search)||x.Email.Contains(search)||x.Phone.Contains(search));var total=await q.CountAsync(ct);return Results.Ok(new{items=await q.OrderBy(x=>x.FullName).Skip((page-1)*pageSize).Take(pageSize).Select(x=>new{x.Id,x.FullName,x.Email,x.Phone,x.StudentCode,Registrations=x.Registrations.Count}).ToListAsync(ct),page,pageSize,total});});
app.Run();

static Dictionary<string,string[]> Validate(object x){var r=new List<ValidationResult>();Validator.TryValidateObject(x,new ValidationContext(x),r,true);var result=r.GroupBy(a=>a.MemberNames.FirstOrDefault()??"request").ToDictionary(a=>a.Key,a=>a.Select(b=>b.ErrorMessage??"Invalid value").ToArray());if(x is EventInput e){if(e.EndTime<=e.StartTime)result["endTime"]=["End time must be later than start time."];if(e.Status is not ("Open" or "Closed"))result["status"]=["Status must be Open or Closed."];}return result;}
static async Task<IResult> CreateEvent(EventInput input,EventDb db,HttpContext http,CancellationToken ct){var errors=Validate(input);if(errors.Count>0)return Results.ValidationProblem(errors);var e=new EventEntity{Name=input.Name.Trim(),Description=input.Description,Category=input.Category,Location=input.Location,Address=input.Address,StartTime=input.StartTime,EndTime=input.EndTime,Capacity=input.Capacity,CoverImage=input.CoverImage,Status=input.Status,CreatedAt=DateTimeOffset.UtcNow,UpdatedAt=DateTimeOffset.UtcNow};db.Events.Add(e);db.AddEventOutbox(e,"EventCreated",http.TraceIdentifier);await db.SaveChangesAsync(ct);return Results.Created($"/events/{e.Id}",EventDto.From(e));}
static async Task<IResult> UpdateEvent(Guid id,EventInput input,EventDb db,HttpContext http,CancellationToken ct){var e=await db.Events.FindAsync([id],ct);if(e is null)return Results.NotFound();var errors=Validate(input);if(errors.Count>0)return Results.ValidationProblem(errors);if(input.Capacity<e.RegisteredCount)return Results.Conflict(new{message="Capacity cannot be lower than active registrations."});e.Name=input.Name.Trim();e.Description=input.Description;e.Category=input.Category;e.Location=input.Location;e.Address=input.Address;e.StartTime=input.StartTime;e.EndTime=input.EndTime;e.Capacity=input.Capacity;e.CoverImage=input.CoverImage;e.Status=input.Status;e.UpdatedAt=DateTimeOffset.UtcNow;db.AddEventOutbox(e,"EventUpdated",http.TraceIdentifier);await db.SaveChangesAsync(ct);return Results.Ok(EventDto.From(e));}
static async Task<IResult> DeleteEvent(Guid id,EventDb db,HttpContext http,CancellationToken ct){var e=await db.Events.FindAsync([id],ct);if(e is null)return Results.NotFound();if(await db.Registrations.AnyAsync(r=>r.EventId==id,ct)){e.Status="Closed";e.UpdatedAt=DateTimeOffset.UtcNow;db.AddEventOutbox(e,"EventUpdated",http.TraceIdentifier);}else{db.AddEventOutbox(e,"EventDeleted",http.TraceIdentifier);db.Events.Remove(e);}await db.SaveChangesAsync(ct);return Results.NoContent();}
static async Task<IResult> RegistrationList(Guid? id,EventDb db,string? search,string? status,int page=1,int pageSize=20,CancellationToken ct=default){page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);var q=db.Registrations.AsNoTracking().Include(x=>x.Event).Include(x=>x.Participant).AsQueryable();if(id.HasValue)q=q.Where(x=>x.EventId==id);if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.RegistrationCode.Contains(search)||x.Participant.FullName.Contains(search)||x.Participant.Email.Contains(search));if(!string.IsNullOrWhiteSpace(status))q=q.Where(x=>x.Status==status);var total=await q.CountAsync(ct);return Results.Ok(new{items=await q.OrderByDescending(x=>x.RegistrationDate).Skip((page-1)*pageSize).Take(pageSize).Select(x=>RegistrationDto.From(x,x.Event)).ToListAsync(ct),page,pageSize,total});}
public record EventInput([property: Required, StringLength(180,MinimumLength=3)]string Name,[property: StringLength(5000)]string Description,[property: Required]string Category,[property: Required]string Location,[property: Required]string Address,DateTimeOffset StartTime,DateTimeOffset EndTime,[property: Range(1,100000)]int Capacity,string? CoverImage,[property: Required]string Status);
public record RegistrationInput([property: Required, StringLength(160,MinimumLength=2)]string FullName,[property: Required, EmailAddress]string Email,[property: Required, Phone]string Phone,string? StudentCode);
public record VerifyInput([property:Required]string RegistrationCode);
public record LookupInput([property:Required,StringLength(320,MinimumLength=4)]string Query);
public record EventDto(Guid Id,string Name,string Description,string Category,string Location,string Address,DateTimeOffset StartTime,DateTimeOffset EndTime,int Capacity,int RegisteredCount,int CheckedInCount,int AvailableSeats,string? CoverImage,string Status){public static EventDto From(EventEntity e)=>new(e.Id,e.Name,e.Description,e.Category,e.Location,e.Address,e.StartTime,e.EndTime,e.Capacity,e.RegisteredCount,e.CheckedInCount,Math.Max(0,e.Capacity-e.RegisteredCount),e.CoverImage,e.Status);public static System.Linq.Expressions.Expression<Func<EventEntity,EventDto>> Map=>e=>new(e.Id,e.Name,e.Description,e.Category,e.Location,e.Address,e.StartTime,e.EndTime,e.Capacity,e.RegisteredCount,e.CheckedInCount,e.Capacity-e.RegisteredCount,e.CoverImage,e.Status);}
public record RegistrationDto(Guid Id,string RegistrationCode,Guid EventId,string EventName,DateTimeOffset EventStartTime,string EventLocation,string EventAddress,string ParticipantName,string Email,string Phone,string Status,DateTimeOffset RegistrationDate,DateTimeOffset? CheckInTime,string QRCodeData){public static RegistrationDto From(Registration r,EventEntity e)=>new(r.Id,r.RegistrationCode,r.EventId,e.Name,e.StartTime,e.Location,e.Address,r.Participant.FullName,r.Participant.Email,r.Participant.Phone,r.Status,r.RegistrationDate,r.CheckInTime,r.QRCodeData);}
public sealed class EventEntity{public Guid Id{get;set;}=Guid.NewGuid();public string Name{get;set;}="";public string Description{get;set;}="";public string Category{get;set;}="";public string Location{get;set;}="";public string Address{get;set;}="";public DateTimeOffset StartTime{get;set;}public DateTimeOffset EndTime{get;set;}public int Capacity{get;set;}public int RegisteredCount{get;set;}public int CheckedInCount{get;set;}public string? CoverImage{get;set;}public string Status{get;set;}="Open";public DateTimeOffset CreatedAt{get;set;}public DateTimeOffset UpdatedAt{get;set;}public int Version{get;set;}public List<Registration> Registrations{get;set;}=[];}
public sealed class Participant{public Guid Id{get;set;}=Guid.NewGuid();public string FullName{get;set;}="";public string Email{get;set;}="";public string Phone{get;set;}="";public string? StudentCode{get;set;}public DateTimeOffset CreatedAt{get;set;}public List<Registration> Registrations{get;set;}=[];}
public sealed class Registration{public Guid Id{get;set;}public string RegistrationCode{get;set;}="";public Guid EventId{get;set;}public EventEntity Event{get;set;}=null!;public Guid ParticipantId{get;set;}public Participant Participant{get;set;}=null!;public DateTimeOffset RegistrationDate{get;set;}public string Status{get;set;}="Registered";public DateTimeOffset? CheckInTime{get;set;}public string QRCodeData{get;set;}="";public DateTimeOffset CreatedAt{get;set;}public DateTimeOffset UpdatedAt{get;set;}}
public sealed class OutboxMessage{public Guid Id{get;set;}=Guid.NewGuid();public Guid EventId{get;set;}public string RoutingKey{get;set;}="";public string Payload{get;set;}="";public DateTimeOffset CreatedAt{get;set;}public DateTimeOffset? PublishedAt{get;set;}public int Attempts{get;set;}}
public sealed class EventDb(DbContextOptions<EventDb> o):DbContext(o){public DbSet<EventEntity> Events=>Set<EventEntity>();public DbSet<Participant> Participants=>Set<Participant>();public DbSet<Registration> Registrations=>Set<Registration>();public DbSet<OutboxMessage> Outbox=>Set<OutboxMessage>();protected override void OnModelCreating(ModelBuilder b){b.Entity<EventEntity>().HasIndex(x=>new{x.Status,x.StartTime});b.Entity<EventEntity>().ToTable(t=>t.HasCheckConstraint("CK_Events_Counts","[Capacity]>0 AND [RegisteredCount]>=0 AND [RegisteredCount]<=[Capacity] AND [CheckedInCount]>=0 AND [CheckedInCount]<=[RegisteredCount]"));b.Entity<Participant>().HasIndex(x=>x.Email).IsUnique();b.Entity<Participant>().Property(x=>x.Email).HasMaxLength(320);b.Entity<Registration>().HasIndex(x=>x.RegistrationCode).IsUnique();b.Entity<Registration>().HasIndex(x=>new{x.EventId,x.ParticipantId}).IsUnique().HasFilter("[Status] <> N'Cancelled'");b.Entity<Registration>().Property(x=>x.Status).HasMaxLength(20);b.Entity<EventEntity>().Property(x=>x.Version).IsConcurrencyToken();b.Entity<OutboxMessage>().ToTable("OutboxMessages");b.Entity<OutboxMessage>().HasIndex(x=>new{x.PublishedAt,x.CreatedAt});}}
public static class OutboxExtensions{public static void AddEventOutbox(this EventDb db,EventEntity e,string type,string correlation){var evt=new BusinessEvent(Guid.NewGuid(),type,DateTimeOffset.UtcNow,correlation,++e.Version,new EventData(null,null,null,null,null,e.Id,e.Name,e.StartTime,e.Capacity,e.RegisteredCount,e.CheckedInCount,e.Description));db.Outbox.Add(new OutboxMessage{EventId=evt.EventId,RoutingKey=type switch{"EventCreated"=>"event.event.created","EventDeleted"=>"event.event.deleted",_=>"event.event.updated"},Payload=JsonSerializer.Serialize(evt),CreatedAt=DateTimeOffset.UtcNow});}public static void AddOutbox(this EventDb db,Registration r,EventEntity e,Participant p,string type,string correlation){var evt=new BusinessEvent(Guid.NewGuid(),type,DateTimeOffset.UtcNow,correlation,e.Version+1,new EventData(r.Id,r.RegistrationCode,p.Id,p.FullName,p.Email,e.Id,e.Name,e.StartTime,e.Capacity,e.RegisteredCount,e.CheckedInCount));e.Version++;db.Outbox.Add(new OutboxMessage{EventId=evt.EventId,RoutingKey=type switch{"ParticipantRegistered"=>"event.participant.registered","ParticipantCancelled"=>"event.participant.cancelled","ParticipantCheckedIn"=>"event.participant.checkedin","EventCreated"=>"event.event.created",_=>"event.event.updated"},Payload=JsonSerializer.Serialize(evt),CreatedAt=DateTimeOffset.UtcNow});}}
public sealed class DatabaseInitializer(IServiceScopeFactory scopes,ILogger<DatabaseInitializer> log):IHostedService{public async Task StartAsync(CancellationToken ct){using var scope=scopes.CreateScope();var db=scope.ServiceProvider.GetRequiredService<EventDb>();await db.Database.MigrateAsync(ct);if(await db.Events.AnyAsync(ct))return;var names=new[]{"Hội thảo Công nghệ tương lai","Ngày hội Khởi nghiệp 2027","Tuần lễ Thiết kế số","AI và Dữ liệu lớn","Ngày hội Tuyển dụng ICTU","An toàn mạng cho mọi người","Festival Sáng tạo sinh viên","Workshop Cloud Native"};for(var i=0;i<names.Length;i++){var e=new EventEntity{Name=names[i],Description="Gặp gỡ chuyên gia, khám phá ý tưởng mới và kết nối cộng đồng sinh viên trong một ngày trải nghiệm thực tế.",Category=new[]{"Công nghệ","Khởi nghiệp","Thiết kế","Học thuật"}[i%4],Location=new[]{"Hội trường A","Trung tâm Sáng tạo","Tòa nhà C"}[i%3],Address="Trường Đại học Công nghệ Thông tin và Truyền thông Thái Nguyên",StartTime=DateTimeOffset.UtcNow.Date.AddDays(15+i*5).AddHours(9),EndTime=DateTimeOffset.UtcNow.Date.AddDays(15+i*5).AddHours(16),Capacity=80+i*10,Status="Open",CoverImage=new[]{"https://images.unsplash.com/photo-1540575467063-178a50c2df87?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1517245386807-bb43f82c33c4?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=1200&q=80"}[i%3],CreatedAt=DateTimeOffset.UtcNow,UpdatedAt=DateTimeOffset.UtcNow};db.Events.Add(e);db.AddEventOutbox(e,"EventCreated","demo-seed");for(var j=0;j<3;j++){var index=i*3+j;var p=new Participant{FullName=$"Người tham dự {index+1:00}",Email=$"participant{index+1:00}@example.test",Phone=$"090000{index+1:0000}",StudentCode=$"ICTU{index+1:00000}",CreatedAt=DateTimeOffset.UtcNow};db.Participants.Add(p);var cancelled=j==2&&i%2==0;var checkedIn=j==0&&i%3==0;var r=new Registration{Id=Guid.NewGuid(),Event=e,Participant=p,RegistrationCode=$"DEMO-{i+1:00}{j+1:00}-{Guid.NewGuid():N}"[..16],RegistrationDate=DateTimeOffset.UtcNow.AddDays(-index),Status=cancelled?"Cancelled":checkedIn?"CheckedIn":"Registered",CheckInTime=checkedIn?DateTimeOffset.UtcNow.AddDays(-index):null,CreatedAt=DateTimeOffset.UtcNow,UpdatedAt=DateTimeOffset.UtcNow};r.QRCodeData="event-checkin:"+r.RegistrationCode;db.Registrations.Add(r);e.RegisteredCount++;db.AddOutbox(r,e,p,"ParticipantRegistered","demo-seed");if(cancelled){e.RegisteredCount--;db.AddOutbox(r,e,p,"ParticipantCancelled","demo-seed");}else if(checkedIn){e.CheckedInCount++;db.AddOutbox(r,e,p,"ParticipantCheckedIn","demo-seed");}}}await db.SaveChangesAsync(ct);log.LogInformation("Initialized event database with 8 demo events and 24 participants.");}public Task StopAsync(CancellationToken ct)=>Task.CompletedTask;}
public sealed class OutboxPublisher(IServiceScopeFactory scopes,IConfiguration cfg,ILogger<OutboxPublisher> log):BackgroundService{protected override async Task ExecuteAsync(CancellationToken stop){while(!stop.IsCancellationRequested){try{await using var scope=scopes.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<EventDb>();var pending=await db.Outbox.Where(x=>x.PublishedAt==null).OrderBy(x=>x.CreatedAt).Take(25).ToListAsync(stop);if(pending.Count==0){await Task.Delay(1000,stop);continue;}var factory=new RabbitMQ.Client.ConnectionFactory{Uri=new Uri(cfg["RabbitMq:Uri"]??Environment.GetEnvironmentVariable("RABBITMQ_URI")??"amqp://guest:guest@localhost:5672/")};await using var conn=await factory.CreateConnectionAsync(stop);await using var ch=await conn.CreateChannelAsync(new RabbitMQ.Client.CreateChannelOptions(publisherConfirmationsEnabled:true,publisherConfirmationTrackingEnabled:true),stop);await ch.ExchangeDeclareAsync("event.topic",RabbitMQ.Client.ExchangeType.Topic,durable:true,autoDelete:false,cancellationToken:stop);await ch.QueueDeclareAsync("dashboard.events",true,false,false,cancellationToken:stop);await ch.QueueDeclareAsync("audit.events",true,false,false,cancellationToken:stop);foreach(var key in new[]{"event.participant.registered","event.participant.cancelled","event.participant.checkedin","event.event.created","event.event.updated","event.event.deleted"}){await ch.QueueBindAsync("dashboard.events","event.topic",key,cancellationToken:stop);await ch.QueueBindAsync("audit.events","event.topic",key,cancellationToken:stop);}foreach(var m in pending){try{using var doc=JsonDocument.Parse(m.Payload);var props=new RabbitMQ.Client.BasicProperties{Persistent=true,MessageId=m.EventId.ToString(),CorrelationId=doc.RootElement.GetProperty("CorrelationId").GetString(),ContentType="application/json"};await ch.BasicPublishAsync("event.topic",m.RoutingKey,true,props,System.Text.Encoding.UTF8.GetBytes(m.Payload),stop);m.PublishedAt=DateTimeOffset.UtcNow;}catch(Exception ex){m.Attempts++;log.LogError(ex,"Outbox publish failed for {MessageId}",m.EventId);}}await db.SaveChangesAsync(stop);}catch(OperationCanceledException)when(stop.IsCancellationRequested){break;}catch(Exception ex){log.LogError(ex,"Outbox dispatcher unavailable; retrying");await Task.Delay(3000,stop);}}}}
